def _force_letterbox_off_in_config():
    try:
        if CONFIG_FILE.exists():
            cfg = json.loads(CONFIG_FILE.read_text(encoding="utf-8"))
        else:
            cfg = {}
        if cfg.get("auto_crop", False):
            cfg["auto_crop"] = False
            CONFIG_FILE.write_text(
                json.dumps(cfg, ensure_ascii=False, indent=2),
                encoding="utf-8"
            )
    except Exception:
        pass

def _force_restore_windows_cursor():
    # Reloads every system cursor from the registry/theme (SPI_SETCURSORS) and frees the mouse
    # (Live Player confines it to the output picture with ClipCursor).
    # Safe to call at any time, any number of times, from any process.
    try:
        ctypes.windll.user32.SystemParametersInfoW(0x0057, 0, None, 0)
    except Exception:
        pass
    try:
        ctypes.windll.user32.ClipCursor(None)
    except Exception:
        pass

_CURSOR_WATCHDOG_SCRIPT = (
    "import ctypes,sys\n"
    "k=ctypes.windll.kernel32\n"
    "k.OpenProcess.restype=ctypes.c_void_p\n"
    "k.WaitForSingleObject.argtypes=[ctypes.c_void_p,ctypes.c_uint32]\n"
    "h=k.OpenProcess(0x00100000,False,int(sys.argv[1]))\n"
    "if h: k.WaitForSingleObject(h,0xFFFFFFFF)\n"
    "ctypes.windll.user32.SystemParametersInfoW(0x0057,0,None,0)\n"
    "ctypes.windll.user32.ClipCursor(None)\n"
)
_cursor_safety_installed = False

def _install_cursor_safety_net():
    # Guarantees the Windows cursor comes back even if this process dies abnormally:
    #  1) atexit / signal handlers / excepthook for normal and semi-normal exits
    #  2) a detached watchdog process that restores the cursor once this PID is gone
    #     (covers kill -9 / Task Manager / crash where no Python code can run)
    global _cursor_safety_installed
    if _cursor_safety_installed:
        return
    _cursor_safety_installed = True
    try:
        atexit.register(_force_restore_windows_cursor)
    except Exception:
        pass

    def _sig_handler(signum, frame):
        _force_restore_windows_cursor()
        sys.exit(0)

    for _name in ("SIGINT", "SIGTERM", "SIGBREAK", "SIGHUP"):
        _sig = getattr(signal, _name, None)
        if _sig is not None:
            try:
                signal.signal(_sig, _sig_handler)
            except (ValueError, OSError, RuntimeError):
                pass
    try:
        _prev_hook = sys.excepthook

        def _hook(exc_type, exc_value, exc_tb):
            _force_restore_windows_cursor()
            _prev_hook(exc_type, exc_value, exc_tb)

        sys.excepthook = _hook
    except Exception:
        pass

    if getattr(sys, "frozen", False):
        return
    try:
        _cmd = [sys.executable, "-c", _CURSOR_WATCHDOG_SCRIPT, str(os.getpid())]
        _base = 0x00000008 | 0x00000200 | 0x08000000  # DETACHED | NEW_PROCESS_GROUP | NO_WINDOW
        try:
            subprocess.Popen(_cmd, creationflags=_base | 0x01000000, close_fds=True,
                             stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except Exception:
            subprocess.Popen(_cmd, creationflags=_base, close_fds=True,
                             stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except Exception as e:
        print(f"[Cursor] watchdog start warning: {e}", flush=True)
