class BITMAPINFOHEADER(ctypes.Structure):
    _fields_ = [
        ("biSize", wintypes.DWORD),
        ("biWidth", wintypes.LONG),
        ("biHeight", wintypes.LONG),
        ("biPlanes", wintypes.WORD),
        ("biBitCount", wintypes.WORD),
        ("biCompression", wintypes.DWORD),
        ("biSizeImage", wintypes.DWORD),
        ("biXPelsPerMeter", wintypes.LONG),
        ("biYPelsPerMeter", wintypes.LONG),
        ("biClrUsed", wintypes.DWORD),
        ("biClrImportant", wintypes.DWORD),
    ]

class BITMAPINFO(ctypes.Structure):
    _fields_ = [("bmiHeader", BITMAPINFOHEADER), ("bmiColors", wintypes.DWORD * 3)]

class PIXELFORMATDESCRIPTOR(ctypes.Structure):
    _fields_ = [
        ("nSize", wintypes.WORD),
        ("nVersion", wintypes.WORD),
        ("dwFlags", wintypes.DWORD),
        ("iPixelType", ctypes.c_byte),
        ("cColorBits", ctypes.c_byte),
        ("cRedBits", ctypes.c_byte),
        ("cRedShift", ctypes.c_byte),
        ("cGreenBits", ctypes.c_byte),
        ("cGreenShift", ctypes.c_byte),
        ("cBlueBits", ctypes.c_byte),
        ("cBlueShift", ctypes.c_byte),
        ("cAlphaBits", ctypes.c_byte),
        ("cAlphaShift", ctypes.c_byte),
        ("cAccumBits", ctypes.c_byte),
        ("cAccumRedBits", ctypes.c_byte),
        ("cAccumGreenBits", ctypes.c_byte),
        ("cAccumBlueBits", ctypes.c_byte),
        ("cAccumAlphaBits", ctypes.c_byte),
        ("cDepthBits", ctypes.c_byte),
        ("cStencilBits", ctypes.c_byte),
        ("cAuxBuffers", ctypes.c_byte),
        ("iLayerType", ctypes.c_byte),
        ("bReserved", ctypes.c_byte),
        ("dwLayerMask", wintypes.DWORD),
        ("dwVisibleMask", wintypes.DWORD),
        ("dwDamageMask", wintypes.DWORD),
    ]

VK_MAP = {
    "esc": 0x1B, "escape": 0x1B,
    "space": 0x20, "tab": 0x09, "enter": 0x0D, "return": 0x0D,
    "backspace": 0x08, "bs": 0x08, "delete": 0x2E, "del": 0x2E,
    "insert": 0x2D, "ins": 0x2D, "home": 0x24, "end": 0x23,
    "pageup": 0x21, "pgup": 0x21, "pagedown": 0x22, "pgdn": 0x22,
    "up": 0x26, "down": 0x28, "left": 0x25, "right": 0x27,
    "f1": 0x70, "f2": 0x71, "f3": 0x72, "f4": 0x73,
    "f5": 0x74, "f6": 0x75, "f7": 0x76, "f8": 0x77,
    "f9": 0x78, "f10": 0x79, "f11": 0x7A, "f12": 0x7B,
    **{str(i): 0x30 + i for i in range(10)},
    **{chr(ord("a") + i): 0x41 + i for i in range(26)},
    "[": 0xDB, "]": 0xDD, ";": 0xBA, "'": 0xDE, "`": 0xC0,
    "\\": 0xDC, "/": 0xBF, "-": 0xBD, "=": 0xBB, "+": 0xBB, ",": 0xBC, ".": 0xBE,
}

MOD_NAMES = {"ctrl": "ctrl", "control": "ctrl", "shift": "shift", "alt": "alt", "menu": "alt"}

def parse_hotkey(spec: str):
    if not spec or not str(spec).strip():
        return None
    s = str(spec).strip().lower()

    if s in ("+", "-"):

        key_name = "=" if s == "+" else "-"
        if key_name not in VK_MAP:
            raise argparse.ArgumentTypeError(f"Unknown key: '{s}'")
        return {"mods": set(), "vk": VK_MAP[key_name]}

    parts = [p.strip() for p in re.split(r"[+\s]+", s) if p.strip()]
    mods = set()
    key_vk = None
    for p in parts:
        if p in MOD_NAMES:
            mods.add(MOD_NAMES[p])
        elif p in VK_MAP:
            key_vk = VK_MAP[p]
        else:
            raise argparse.ArgumentTypeError(f"Unknown key: '{p}'")
    if key_vk is None:
        raise argparse.ArgumentTypeError(f"No main key specified: '{spec}'")
    return {"mods": mods, "vk": key_vk}

def flush_hotkey_edge(hk):
    # GetAsyncKeyState's "pressed since last call" bit (edge detection) keeps accumulating while
    # nobody polls that key. A key pressed while it was unassigned (e.g. typing it into the
    # hotkey box in the GUI) would otherwise fire once on the first poll after it gets assigned.
    # Reading the key once here clears that stale bit.
    if hk is None:
        return
    try:
        user32.GetAsyncKeyState(hk["vk"])
        for _vk in (0x11, 0x10, 0x12):
            user32.GetAsyncKeyState(_vk)
    except Exception:
        pass

def is_hotkey_down(hk, edge: bool = False) -> bool:
    if hk is None:
        return False
    if "ctrl" in hk["mods"] and not (user32.GetAsyncKeyState(0x11) & 0x8000):
        return False
    if "shift" in hk["mods"] and not (user32.GetAsyncKeyState(0x10) & 0x8000):
        return False
    if "alt" in hk["mods"] and not (user32.GetAsyncKeyState(0x12) & 0x8000):
        return False
    state = user32.GetAsyncKeyState(hk["vk"])
    if edge:
        return bool(state & 0x0001)
    return bool(state & 0x8000)

def parse_size(s: str) -> tuple[int, int]:
    a, b = s.lower().split("x")
    return int(a), int(b)

def parse_bgr(s: str) -> tuple[int, int, int]:
    parts = [p.strip() for p in s.replace(" ", "").split(",")]
    if len(parts) != 3:
        raise argparse.ArgumentTypeError("Color must be three values R,G,B")
    r, g, b = (int(parts[0]), int(parts[1]), int(parts[2]))
    for v in (r, g, b):
        if not 0 <= v <= 255:
            raise argparse.ArgumentTypeError("Color components must be 0-255")
    return (b, g, r)

def parse_edge_dilation(s: str):
    s = s.strip()
    if not s or s == "0":
        return 0
    parts = [p.strip() for p in s.replace(" ", "").split(",")]
    vals = [int(p) for p in parts]
    if len(vals) == 1:
        return vals[0]
    if len(vals) == 2:
        return vals
    raise argparse.ArgumentTypeError("edge-dilation accepts only 1 or 2 values")

EMA_MAX = 0.60

EMA_LEVELS = [
    ("Off", 0.00),
    ("Low", 0.30),
    ("Medium", 0.40),
    ("High", 0.50),
    ("Ultra", 0.60),
]
EMA_STEP_GRID = [v for _, v in EMA_LEVELS]

def ema_value_to_label(value: float) -> str:
    v = float(value)
    best_label, best_val = EMA_LEVELS[0]
    best_diff = abs(v - best_val)
    for label, lv in EMA_LEVELS:
        diff = abs(v - lv)
        if diff < best_diff:
            best_diff = diff
            best_label, best_val = label, lv
    return best_label

def ema_label_to_value(label: str) -> float:
    for l, v in EMA_LEVELS:
        if l == label:
            return v
    return 0.00

def clamp_ema_value(value: float) -> float:
    try:
        v = float(value)
    except (TypeError, ValueError):
        return 0.00
    if v < 0.0:
        return 0.00
    if v > EMA_MAX:
        return EMA_MAX
    return v

def ema_step_value(current: float, increase: bool) -> float:
    cur = round(float(current), 2)
    if increase:
        for v in EMA_STEP_GRID:
            if v > cur + 1e-9:
                return v
        return EMA_STEP_GRID[-1]
    else:
        for v in reversed(EMA_STEP_GRID):
            if v < cur - 1e-9:
                return v
        return EMA_STEP_GRID[0]

# ---------------------------------------------------------------------------
# Auto Mode EMA table. Each row is (min strength, EMA decay): the LAST row whose min strength <= the slider
# value is used (below the first non-zero row -> OFF 0.00).
# Levels: OFF 0.00 / Low 0.30 / Medium 0.40 / High 0.50 / Ultra 0.60.
# The EMA value does NOT depend on Depth Linear Compression (ON uses exactly the same rows as OFF).
# ---------------------------------------------------------------------------
_EMA_ROWS_STD = [(0.0, 0.00), (1.5, 0.30), (2.0, 0.40), (2.5, 0.50), (3.0, 0.60)]
# VDA models (VDA-S, VDA-S Metric): flicker reduction (EMA) is OFF at every strength in Auto Mode.
_EMA_ROWS_VDA = [(0.0, 0.00)]
_EMA_ROWS_VDA_METRIC = [(0.0, 0.00)]
# Other models: previous curve, unchanged (old rule was "strength <= max", hence the +1e-6).
_EMA_ROWS_DEFAULT = [(0.0, 0.00), (0.5 + 1e-6, 0.30), (1.0 + 1e-6, 0.40), (1.5 + 1e-6, 0.50), (2.5 + 1e-6, 0.60)]

_AUTO_EMA_TABLE = {
    "zipdepth":      _EMA_ROWS_STD,
    "dav2_s":        _EMA_ROWS_STD,
    "distill_any_s": _EMA_ROWS_STD,
    "vda_s":         _EMA_ROWS_VDA,
    "vda_s_metric":  _EMA_ROWS_VDA_METRIC,
    "default":       _EMA_ROWS_DEFAULT,
}

def auto_ema_from_table(depth_model, divergence: float, comp_on: bool = False) -> float:
    # comp_on is accepted for compatibility but ignored: same EMA with Depth Linear Compression ON or OFF.
    rows = _AUTO_EMA_TABLE.get(depth_model) or _AUTO_EMA_TABLE["default"]
    d = float(divergence)
    ema = rows[0][1]
    for min_div, val in rows:
        if d >= min_div - 1e-9:
            ema = val
        else:
            break
    return ema

# ---------------------------------------------------------------------------
# Auto Mode edge fix table (measured 'recommended edge fix' of the Edge Fix Meter).
# Key: warp/fill method -> depth model -> (compression OFF, compression ON); each list holds the edge fix for
# strength 0.5, 1.0, 1.5 ... 5.0 (10 steps). A strength in between uses the next step up (ceil to 0.5).
# Depth Linear Compression ON only applies to models in DEPTH_LINEAR_COMP_PARAMS. EMA is NOT affected.
# Combinations missing from the table fall back to the previous rule (_compute_auto_edge_ema_legacy).
# ---------------------------------------------------------------------------
