class ColorPickLineEdit(QLineEdit):
    """Read-only 'R,G,B' field (plain white, default styling). Clicking it opens a colour picker
    (palette, spectrum and a screen eyedropper). The stored text format stays 'R,G,B', so the
    config file and the --cursor-color / --cursor-outline arguments are unchanged."""

    def __init__(self, text: str = "255,255,255", title_fn=None, parent=None):
        super().__init__(parent)
        self._title_fn = title_fn
        self.setReadOnly(True)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setText(text)

    @staticmethod
    def _parse(text: str):
        try:
            parts = [int(p) for p in str(text).replace(" ", "").split(",")]
            if len(parts) == 3 and all(0 <= v <= 255 for v in parts):
                return tuple(parts)
        except Exception:
            pass
        return None

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            self._pick()
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseDoubleClickEvent(self, event):
        self._pick()
        event.accept()

    def _pick(self):
        rgb = self._parse(self.text()) or (255, 255, 255)
        title = self._title_fn() if callable(self._title_fn) else ""
        col = QColorDialog.getColor(
            QColor(*rgb), self.window(), title,
            QColorDialog.ColorDialogOption.DontUseNativeDialog,
        )
        if col.isValid():
            self.setText(f"{col.red()},{col.green()},{col.blue()}")


class VideoPathLineEdit(QLineEdit):
    """Read-only path box: Backspace / Delete clears the whole path at once."""
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setReadOnly(True)
        self.setClearButtonEnabled(False)

    def keyPressEvent(self, event):
        if event.key() in (Qt.Key.Key_Backspace, Qt.Key.Key_Delete):
            self.clear()
            event.accept()
            return
        super().keyPressEvent(event)


class HotkeyLineEdit(QLineEdit):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setClearButtonEnabled(False)

    def keyPressEvent(self, event):
        key = event.key()
        if key in (Qt.Key.Key_Control, Qt.Key.Key_Shift, Qt.Key.Key_Alt, Qt.Key.Key_Meta):
            event.accept()
            return
        if key in (Qt.Key.Key_Backspace, Qt.Key.Key_Delete):
            self.clear()
            event.accept()
            return

        mods = []
        if event.modifiers() & Qt.KeyboardModifier.ControlModifier: mods.append("ctrl")
        if event.modifiers() & Qt.KeyboardModifier.ShiftModifier: mods.append("shift")
        if event.modifiers() & Qt.KeyboardModifier.AltModifier: mods.append("alt")

        key_text = ""
        if Qt.Key.Key_F1 <= key <= Qt.Key.Key_F12: key_text = f"f{key - Qt.Key.Key_F1 + 1}"
        elif key == Qt.Key.Key_Escape: key_text = "esc"
        elif key == Qt.Key.Key_Space: key_text = "space"
        elif key == Qt.Key.Key_Tab: key_text = "tab"
        elif key in (Qt.Key.Key_Return, Qt.Key.Key_Enter): key_text = "enter"
        elif key == Qt.Key.Key_Up: key_text = "up"
        elif key == Qt.Key.Key_Down: key_text = "down"
        elif key == Qt.Key.Key_Left: key_text = "left"
        elif key == Qt.Key.Key_Right: key_text = "right"
        elif key == Qt.Key.Key_BracketLeft: key_text = "["
        elif key == Qt.Key.Key_BracketRight: key_text = "]"
        elif 0x20 <= key <= 0x7E: key_text = chr(key).lower()
        else:
            event.ignore()
            return

        if key_text:
            parts = mods + [key_text]
            self.setText("+".join(parts))
        event.accept()

class EmaComboBox(QComboBox):

    valueChanged = Signal(float)

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setEditable(False)
        for label, _ in EMA_LEVELS:
            self.addItem(label)
        self.currentIndexChanged.connect(self._emit_value_changed)

    def _emit_value_changed(self, _index: int):
        self.valueChanged.emit(self.value())

    def value(self) -> float:
        return ema_label_to_value(self.currentText())

    def setValue(self, value: float):
        label = ema_value_to_label(value)
        idx = self.findText(label)
        if idx >= 0:
            self.setCurrentIndex(idx)

class _MaxOrIntValidator(QIntValidator):
    """Combo input: digits in [lo, hi] or the label 'MAX' (= no limit); typing is case-insensitive."""

    def __init__(self, lo, hi, max_label, parent=None):
        super().__init__(lo, hi, parent)
        self._max_label = max_label.lower()

    def validate(self, text, pos):
        s_ = text.strip().lower()
        if s_ == "":
            return (QValidator.Acceptable, text, pos)
        if s_ == self._max_label:
            return (QValidator.Acceptable, text, pos)
        if self._max_label.startswith(s_):
            return (QValidator.Intermediate, text, pos)
        return super().validate(text, pos)


class Live3DGui(QMainWindow):
    def __init__(self):
        super().__init__()
        self.lang = _load_ui_language()
        self.process: QProcess | None = None
        self._build_ui()
        self._load_config()
        # First run (no config file) never reaches _apply_config(), so apply the Auto Mode state here:
        # in Auto Mode the Edge Fix / EMA / Depth AA widgets must be in their auto state from the start.
        self._update_auto_mode_enabled_state()
        if self.chk_auto_mode.isChecked():
            self._apply_auto_values()
        self._apply_language()
        self.setWindowTitle(self.t("title"))
        self.resize(880, 600)

        atexit.register(_force_letterbox_off_in_config)
        _force_restore_windows_cursor()
        self._register_force_exit_handlers()

    def _register_force_exit_handlers(self):
        def _handler(signum, frame):
            _force_letterbox_off_in_config()

            sys.exit(0)

        for sig_name in ("SIGINT", "SIGTERM", "SIGBREAK", "SIGHUP"):
            sig = getattr(signal, sig_name, None)
            if sig is not None:
                try:
                    signal.signal(sig, _handler)
                except (ValueError, OSError, RuntimeError):

                    pass

        prev_excepthook = sys.excepthook

        def _excepthook(exc_type, exc_value, exc_tb):
            _force_letterbox_off_in_config()
            prev_excepthook(exc_type, exc_value, exc_tb)

        sys.excepthook = _excepthook

    def t(self, key: str) -> str:
        lang = getattr(self, "lang", "en")
        return TEXTS.get(lang, TEXTS["en"]).get(key, key)

    def _is_running(self) -> bool:
        return self.process is not None and self.process.state() != QProcess.ProcessState.NotRunning

